={{ 
(() => {
  const number = $('SetFieldsBasic').first().json.phone;
  const text = $json.text || "";
  const safeText = text.replace(/\\/g, "\\\\").replace(/"/g, '\\"').replace(/\n/g, "\\n");
  return `{
    "number": "${number}",
    "text": "${safeText}",
    "delay": 3000
  }`;
})()
}}

